// 隔离共享候选：原玩家守卫、同候选权源和原Office账共同完成四项真实办理。
#include "political_succession_world.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {namespace {
Status available(const WorldBundle& w){if(!w.catalog->political_successions||!w.political_successions||!w.politics_enabled()||!w.catalog->organization||!w.catalog->organization->enabled||!w.family_life_enabled()||!w.catalog->task_message_notices||!w.tasks.message_notices||!w.tasks.message_handoffs||!w.catalog->tasks||!w.catalog->common)return common_failure("PoliticalSuccessionProfileRequired");
 // 空账也须核每项作者原辖区；此处不以当前失控否定先前合法历史。
 for(const auto& row:w.catalog->political_successions->policies.rows()){const auto& p=row.second;const auto* j=w.catalog->politics->jurisdictions.find(p.jurisdiction_id);if(!j||j->id!=p.jurisdiction_id||j->revision!=0||j->office_id!=p.leader_office_id||j->seat_place_id!=p.seat_place_id||j->political_organization_id!=p.organization_id||j->controlling_organization_id!=p.organization_id)return common_failure("PoliticalSuccessionOriginalSeatRequired",p.id);}
 return common_success();}
// 复用原PoliticsEffects具体字段，空Done不能冒称对应本次真实继位source。
bool actual_result(const CommitResult& r,const StableId& source,const StableId& office){if(!r.ok||!r.details||!is_political_succession_command(r.kind))return false;const auto* e=std::get_if<PoliticsEffects>(&r.details->data);return e&&e->appointment_id.empty()&&e->fact_ids==std::vector<StableId>{source}&&e->receipt_ids==(office.empty()?std::vector<StableId>{}:std::vector<StableId>{office});}
Status player(const WorldBundle& w,const StableId& actor,const PoliticalSuccessionCommand& c){auto guard=command_common_guard(w,actor,political_succession_command_kind(c));if(!guard.ok)return guard;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("PoliticalSuccessionPlayerCommandRequired");}
}
PoliticalSuccessionWorldAccess::PoliticalSuccessionWorldAccess(const WorldBundle& w,TaskMessageNoticeServices notices)
 :world_(w),military_(w.political_takeover_enabled()?std::optional<MilitaryAccess>{w.services.military_access()}:std::nullopt),
 occupations_(w.political_takeover_enabled()?std::optional<PoliticalSuccessionOccupationContext>{PoliticalSuccessionOccupationContext{w.political_takeover,*w.catalog->political_takeover,w.military,*w.catalog->military,*military_}}:std::nullopt),
 territory_{w.common,w.politics,*w.catalog->politics,occupations_?&*occupations_:nullptr},notices_(std::move(notices)),
 nominations_{w.common,*w.catalog->common,w.organization,*w.catalog->organization,w.local_economy,w.services,*w.catalog->political_successions,w.political_successions->nominations,w.family_death_read(),[this](const PoliticalSuccessionPolicy& policy,Integer tick,const StableId& boundary){return validate_political_succession_seat(territory_,policy,tick,boundary);},[&w](Integer tick,const StableId& boundary){return read_political_succession_player_before_fact(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,boundary);},&w.political_successions->accessions},
 sources_{nominations_,w.family_life,[this](const StableId& actor,const StableId& binding){const auto& w=world_;return read_delivered_task_death_notice(w.common,w.tasks,*w.catalog->tasks,*w.catalog->common,*w.catalog->task_message_notices,*w.tasks.message_notices,*w.tasks.message_handoffs,notices_.validate,actor,binding);}},context_{sources_,*w.political_successions,actual_result}{}
Outcome<std::unique_ptr<PoliticalSuccessionWorldAccess>> PoliticalSuccessionWorldAccess::create(const WorldBundle& w){auto valid=available(w);if(!valid.ok)return {false,{},valid.error};auto notices=make_task_message_notice_services(w);if(!notices.ok)return {false,{},notices.error};if(!notices.value)return {false,{},common_failure("PoliticalSuccessionNoticeReadRequired").error};return {true,std::unique_ptr<PoliticalSuccessionWorldAccess>{new PoliticalSuccessionWorldAccess(w,std::move(*notices.value))},{}};}
// 仅枚举本人的真实实交观察索引，远方发信/尚未交付均不进入此候选列表。
PoliticalSuccessionViewContext PoliticalSuccessionWorldAccess::view()const{return {context_,[this](const StableId& actor)->Outcome<std::vector<StableId>>{const auto& w=world_;std::vector<StableId> ids;const auto found=w.tasks.message_handoffs->observed_by.find(actor);if(found==w.tasks.message_handoffs->observed_by.end())return {true,std::move(ids),{}};for(const auto& id:found->second){const auto* handoff=w.tasks.message_handoffs->receipts.find(id);if(!handoff)return {false,{},common_failure("TaskMessageHandoffObserverIndexMismatch",id).error};if(handoff->recipient_actor_id!=actor)continue;const auto binding=w.tasks.message_notices->task_to_binding.find(handoff->task_id);if(binding!=w.tasks.message_notices->task_to_binding.end())ids.push_back(binding->second);}return {true,std::move(ids),{}};}};}
// 初始化只在明确新profile下生成空独立账，不产生提名或补造首任Office。
Status initialize_political_succession_world_in_candidate(WorldBundle& w){if(!w.catalog->political_successions)return w.political_successions?common_failure("PoliticalSuccessionProfileMismatch"):common_success();if(w.common.tick()!=0||w.political_successions)return common_failure("PoliticalSuccessionInitialStateRequired");w.political_successions.emplace();return validate_political_succession_world(w);}
// 完整Family/Birth/Legacy/Task实交与军事控制先验之后，才核正式政治史和永久提交。
Status validate_political_succession_world(const WorldBundle& w){auto layout=validate_political_succession_layout(w.common,w.catalog->identity.module_versions,w.political_successions?&*w.political_successions:nullptr);if(!layout.ok)return layout;if(bool(w.catalog->political_successions)!=w.political_successions.has_value())return common_failure("PoliticalSuccessionProfileMismatch");if(!w.catalog->political_successions)return common_success();auto read=PoliticalSuccessionWorldAccess::create(w);if(!read.ok)return {false,{},read.error};return validate_political_successions(read.value->context());}
Outcome<PoliticalSuccessionQuote> prepare_political_succession_world(const WorldBundle& w,const StableId& actor,const PoliticalSuccessionCommand& c){auto valid=player(w,actor,c);if(!valid.ok)return {false,{},valid.error};auto read=PoliticalSuccessionWorldAccess::create(w);if(!read.ok)return {false,{},read.error};return preview_political_succession(read.value->context(),actor,c);}
Outcome<PoliticsEffects> commit_political_succession_world(WorldBundle& w,const StableId& actor,const PoliticalSuccessionCommand& c,const PoliticalSuccessionQuote& quote){auto valid=player(w,actor,c);if(!valid.ok)return {false,{},valid.error};auto read=PoliticalSuccessionWorldAccess::create(w);if(!read.ok)return {false,{},read.error};auto result=apply_political_succession_in_candidate(w.common,w.organization,*w.political_successions,read.value->context(),actor,c,quote);if(!result.ok)return {false,{},result.error};return {true,{{},{result.value.source_fact_id},result.value.office_change_fact_id.empty()?std::vector<StableId>{}:std::vector<StableId>{result.value.office_change_fact_id}},{}};}
Outcome<BoundaryValue> query_political_succession_world(const WorldBundle& w,const StableId& place,Integer cursor){auto read=PoliticalSuccessionWorldAccess::create(w);if(!read.ok)return {false,{},read.error};auto view=read.value->view();return query_political_successions(view,place,cursor);}
Status bind_political_succession_result_world(WorldBundle& w,const StableId& source,const StableId& actor,Integer request,const CommitResult& result){if(!w.political_successions||!w.catalog->political_successions||source.empty()||!is_political_succession_command(result.kind))return common_failure("PoliticalSuccessionNewSourceRequired");return bind_political_succession_player_result(w.common,*w.political_successions,source,actor,request,result,actual_result);}
}
